<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>DVD Logo Bounce</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            background-color: #000;
            font-family: Arial, sans-serif;
        }

        canvas {
            display: block;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas"></canvas>

    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        let width, height;

        function resize() {
            width = window.innerWidth;
            height = window.innerHeight;
            canvas.width = width;
            canvas.height = height;
        }

        window.addEventListener('resize', resize);
        resize();

        const dvd = {
            x: width / 2,
            y: height / 2,
            radius: 60,
            speedX: 3,
            speedY: 3,
            text: "DVD"
        };

        function drawDvd() {
            ctx.clearRect(0, 0, width, height);

            // Draw the DVD logo (simplified as a circle with text)
            ctx.beginPath();
            ctx.arc(dvd.x, dvd.y, dvd.radius, 0, Math.PI * 2);
            ctx.fillStyle = '#1a1a2e';
            ctx.fill();
            ctx.strokeStyle = '#e94560';
            ctx.lineWidth = 3;
            ctx.stroke();

            // Add inner circle detail
            ctx.beginPath();
            ctx.arc(dvd.x, dvd.y, dvd.radius * 0.7, 0, Math.PI * 2);
            ctx.fillStyle = '#16213e';
            ctx.fill();

            // Draw text
            ctx.font = 'bold 48px Arial';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillStyle = '#fff';
            ctx.fillText(dvd.text, dvd.x, dvd.y);
        }

        function update() {
            dvd.x += dvd.speedX;
            dvd.y += dvd.speedY;

            // Bounce off walls
            if (dvd.x - dvd.radius < 0 || dvd.x + dvd.radius > width) {
                dvd.speedX *= -1;
            }
            if (dvd.y - dvd.radius < 0 || dvd.y + dvd.radius > height) {
                dvd.speedY *= -1;
            }
        }

        function animate() {
            update();
            drawDvd();
            requestAnimationFrame(animate);
        }

        animate();
    </script>
</body>
</html>
